document.addEventListener('DOMContentLoaded', () => {
    const triggers = document.querySelectorAll('.disclosure-trigger');

    triggers.forEach(trigger => {
        // Find the panel associated with this trigger
        // Based on structure: h2 > button.disclosure-trigger, then .details is next sibling of h2
        const panel = trigger.closest('h2').nextElementSibling;

        // Initialize state: collapsed by default
        trigger.setAttribute('aria-expanded', 'false');
        panel.hidden = true;

        trigger.addEventListener('click', () => {
            const isExpanded = trigger.getAttribute('aria-expanded') === 'true';

            // Toggle state
            trigger.setAttribute('aria-expanded', !isExpanded);
            panel.hidden = isExpanded;
        });
    });
});

