  await page.goto(filePath);

  // Inject axe-core
  await page.addScriptTag({ path: '/tmp/axe.min.js' });

  // Run axe
  const results = await page.evaluate(async () => {
    return await window.axe.run();
  });

  await browser.close();

  const wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
  const bp = results.violations.filter(v => v.tags.includes('best-practice'));

  console.log(JSON.stringify({
    wcag: wcag.map(v => ({ id: v.id, impact: v.impact, nodes: v.nodes.length, targets: v.nodes.map(n => n.target) })),
    bp: bp.map(v => ({ id: v.id, targets: v.nodes.map(n => n.target) }))
  }, null, 2));

  process.exit(wcag.length > 0 ? 1 : 0);
})();

